"""Package specs and hashes around inactive exported model; no inference."""
import hashlib,json,shutil,sys
from pathlib import Path
from data import ROOT,PARENT,RESULTS,save

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 out=PARENT/'portable-v1';r=RESULTS.parent/'portable-v1';summary=json.loads((r/'summary.json').read_text(encoding='utf-8'));selection=json.loads((ROOT/'selection.json').read_text(encoding='utf-8'));freeze=json.loads((ROOT/'freeze.json').read_text(encoding='utf-8'));spec={'status':'Inactive research candidate; no app switch/document qualification/publicmodel/iPhone claim','format':'Standard ONNX opset17, FP32, CPUExecutionProvider; customop none','modelSha256':sha(out/'model.onnx'),'modelBytes':(out/'model.onnx').stat().st_size,'inputs':{'x':{'type':'FLOAT32','layout':'BCHW','channels':'BGR','shape':['batch',3,48,'input_width'],'widthMin':320,'widthMax':960},'valid_width':{'type':'INT64','shape':['batch'],'bounds':'1<=valid_width<=input_width','purpose':'Reject-head mean frame mask only. Does not hide or trim CTC outputs.'}},'outputs':{'probabilities':{'type':'FLOAT32','shape':['batch','time_steps',438],'operation':'Full438 softmax, unchanged dictionary denominator; no ASCII renormalization'},'reject_probability':{'type':'FLOAT32','shape':['batch'],'operation':'Independent sigmoid reject; uncalibrated'}},'preprocessing':{'input':'Original RGB24 wholeline crop retaining every supplied nonwhite RGB sample; bbox+2originalpixels, original crop offset separately retained','orientation':'Natural single baseline/relative glyph heights/internal gaps retained; no glyph isolation/case/lexicon normalization','inputWidth':'floor(48 * max(320/48, originalCropWidth/originalCropHeight)); refuse if >960','validWidth':'min(inputWidth, ceil(48*originalCropWidth/originalCropHeight))','sampling':'Center-coordinate bilinear in float64 on original RGB byte pixels, channel order reversed to BGR. xs=clamp((j+0.5)*originalWidth/validWidth-0.5,0,originalWidth-1); ys=clamp((i+0.5)*originalHeight/48-0.5,0,originalHeight-1). floor(value+0.5) to uint8-compatible numeric range, then FP32.','normalization':'FP32 steps: (roundedPixels / float32(255) - float32(0.5)) / float32(0.5); zero FP32 rightpadding, not white pixels. Preserve validWidth and original offsets.','referenceSourceSha256':freeze['preprocessSha256'],'referenceSourceFile':'image_tensor.py','officialHfImageProcessorIdentityClaim':False,'productionWindowsByteParityClaim':False},'ctc':{'dictionarySize':438,'dictionaryFile':'dictionary.json','dictionarySha256':sha(out/'dictionary.json'),'blankIndex':0,'spaceIndex':437,'unkAdded':False,'decode':'AllT greedy argmax over438 (ties lowest index); skipblank0; consecutive same nonblank collapse; blank resets previous. Text literal unchanged.','confidence':'MAX emitted-class probability over each consecutive run; line diagnostic minimum across emitted pieces. Not average, not calibrated probability of correctness.','intervals':'Start inclusive/End exclusive time-step indices from original argmax sequence','paddingRule':'Decode fullT. If any emitted End*inputWidth > validWidth*T, refuse supported-source claim; never drop terminal predictions to repair text.','frameMeanMask':'Exact integer inequality (2*t+1)*inputWidth < 2*T*validWidth; model reject mean only','sourcePositionMapping':'ScaledX=t/T*inputWidth; OriginalX=framedOriginalX+ScaledX/validWidth*framedOriginalWidth; height stays original wholeline. SourceBox is CTC estimate, not exact glyph-outline evidence; original ink/ownership/provenance proof remains separate.'},'diagnosticAcceptance':{'minimumCtcConfidence':.8,'maximumRejectProbability':.05,'required':'Nonempty, every output character printableASCII32..126, allintervals supported; no output correction/lexicon/whitelist','limits':'Same frozen comparison thresholds retained for report; new model has increased correct-lowCTC review burden. Do not interpret as calibrated or source-domain proof.'},'trainingProvenance':{'foundation':'PaddlePaddle/en_PP-OCRv5_mobile_rec_safetensors','foundationRevision':freeze['assetReceipt']['revision'],'foundationWeightsSha256':freeze['assetReceipt']['files']['model.safetensors']['sha256'],'declaredLicense':'Apache-2.0 per pinned officialHF receipt','checkpoint':selection['selected']['path'],'checkpointSha256':selection['selected']['sha256'],'trainingProtocolSha256':freeze['protocolSha256'],'parameters':'Official CNN/encoder/full438head plus reject121; originalclass/config/normepsilon1e-6 retained, BNstats fixed','data':'New independent fictional literals; train8/dev4 Latin families disjoint, mono50percent/natural50percent; no realschooldata/olddevfont train transfer/oldliteral training. CJK/mixed wholeline negative controls only.','oldNativeOnnxIdentityClaim':False,'oldZeroWrongGateChanged':False},'fidelity':summary,'limitations':['Fresh development consumed, no final qualification. Sawarabi remains reserved.','WholeJapanese fields have out-of-vocabulary characters; do not oracle-cut prefix or credit ASCII suffix as whole-field.','Interior damage/clipping can be accepted; crop pixels cannot prove completeness/script origin/cell affiliation.','iOS repository not edited; CoreML not attempted; iPhone inference/memory unmeasured.','No automatic app activation, publicmodel release, commit or push.']};save(out/'metadata.json',spec);save(r/'metadata.json',spec);reference=Path(__file__).parents[1]/'image_tensor.py';assert sha(reference)==freeze['preprocessSha256'];(out/'image_tensor.py').write_bytes(reference.read_bytes())
 text='''# Inactive English V5 font-balanced research package

Standard ONNX FP32, full438 dictionary, independent reject probability. This is the selected newly adapted officialTorch model, not a faithful transplant of the previous nativeONNX model. The earlier strict transplant failure and zero-wrong-accept training records remain unchanged.

Load model.onnx locally with ONNX Runtime CPU. Inputs: x float32[B,3,48,W], BGR, W320..960; valid_width int64[B]. Outputs: probabilities float32[B,T,438], reject_probability float32[B]. Metadata defines exact originalpixel preprocessing, dictionary/blank/space, CTC max-run confidence, fullT padding refusal, and position mapping. image_tensor.py is the pinned Python reference. CTC SourceBox is an estimate and does not establish original ink ownership.

Newmodel Torch/ONNX dynamicshape and fixeddev raw comparisons are in summary.json/JSONL receipts in research-results. Numeric differences and confidence/review tradeoffs are recorded rather than repaired. The training stage was pre-registered without exports; this separate portable-v1 stage was requested after fixeddev usefulness evidence. No more training occurred.

Weights stay outsideGit. No final/modelpublication/appactivation/iOS edit. CoreML/iPhone execution not assessed. English specialist cannot represent wholeJapanese mixed fields; suffix accuracy is not wholefield or document qualification. Interior damage and crop-source contradictions remain limitations. Declared officialfoundation license Apache-2.0; provenance/checkpoint/preprocess SHA are in metadata.json.
'''
 (out/'README.md').write_text(text,encoding='utf-8',newline='\n');(r/'README.md').write_text(text,encoding='utf-8',newline='\n');save(r/'package-file-receipt.json',{'scope':'External inactive package, models remain outsideGit','files':{p.name:{'bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(out.iterdir()) if p.is_file()},'allDevelopmentRawDecisionsMatch':summary['allDevelopmentTextIntervalPaddingAcceptEqual'],'selectedCheckpointUnchanged':sha(selection['selected']['path'])==selection['selected']['sha256']});print(json.dumps({'modelBytes':spec['modelBytes'],'modelSha256':spec['modelSha256'],'allDevelopmentRawDecisionsMatch':summary['allDevelopmentTextIntervalPaddingAcceptEqual']}))
if __name__=='__main__':main()
